#!/usr/bin/env bun
/**
 * gas-localnet.ts — Measure real on-chain gas for every Veil entry point on a local Sui network.
 *
 * Every number this prints comes from the `effects.gasUsed` of a transaction actually executed
 * against a running `sui start` localnet (validators + fullnode + faucet), with real Groth16
 * proofs generated by snarkjs against the compiled circuit artifacts. Nothing is estimated.
 *
 * Usage (from repo root):
 *   # 1. a localnet built from the same Sui rev that contracts/Move.lock pins
 *   RUST_LOG=off sui start --with-faucet --force-regenesis &
 *   # 2. circuit artifacts: bash scripts/bench/setup-circuits.sh
 *   # 3. compiled package bytecode
 *   (cd contracts && sui move build --dump-bytecode-as-base64 --no-tree-shaking > /tmp/veil-bytecode.json)
 *   # 4. run
 *   cd scripts && bun run bench/gas-localnet.ts --bytecode /tmp/veil-bytecode.json [--json out.json]
 *
 * Flow (pool epoch = 60 s, the contract's minimum, so timelocks resolve within a run):
 *   epoch E0: publish, create_pool, faucet, 5x deposit_and_register (incl. inflation probe), update_commitment_root,
 *             propose_withdraw_vk, create_compliance_config, admin ops, groth16 micro-benchmarks
 *   epoch E1: shielded_transfer, replay (expected abort), zk_withdraw, compliant_transfer,
 *             and a front-running probe: zk_withdraw with a recipient other than the one the
 *             proof's recipientHash commits to, and an inflation probe (withdraw more than was deposited).
 */
import { readFileSync, writeFileSync } from "fs";
import { dirname, join } from "path";
import { fileURLToPath } from "url";

import { Ed25519Keypair } from "@mysten/sui/keypairs/ed25519";
import { Transaction } from "@mysten/sui/transactions";
import { SuiJsonRpcClient } from "@mysten/sui/jsonRpc";
import { requestSuiFromFaucetV2 } from "@mysten/sui/faucet";
import { buildPoseidon } from "circomlibjs";
import { execFileSync } from "child_process";

import { proofToSuiBytes, publicInputsToSuiBytes, vkToSuiBytes } from "../src/proof-converter.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const CIRCUITS = join(__dirname, "..", "..", "circuits");

const arg = (name: string, dflt?: string) => {
  const i = process.argv.indexOf(name);
  return i !== -1 ? process.argv[i + 1] : dflt;
};
const RPC = arg("--rpc", "http://127.0.0.1:9000")!;
const FAUCET = arg("--faucet", "http://127.0.0.1:9123")!;
const BYTECODE = arg("--bytecode");
const JSON_OUT = arg("--json");
if (!BYTECODE) throw new Error("--bytecode <file from `sui move build --dump-bytecode-as-base64`> is required");

const EPOCH_MS = 60_000n;
const THRESHOLD = 1_000_000_000n;
const DENOM = 100_000_000n; // DENOM_SMALL in pool.move
const P = 21888242871839275222246108078558513925199295690275140998023894059022486755617n; // BN254 r

const D = { COMMITMENT: 1n, NULLIFIER: 2n, TX_AMOUNT: 3n, CRED_LEAF: 4n, COMPL_NF: 5n, CONTEXT: 6n, WD_NF: 7n, RECIPIENT: 8n };
const DEPTH = 20;

// --------------------------------------------------------------------------------------------
const client = new SuiJsonRpcClient({ url: RPC, network: "localnet" });
const admin = new Ed25519Keypair();
const mallory = new Ed25519Keypair();

type Row = {
  label: string;
  status: string;
  computationCost: number;
  storageCost: number;
  storageRebate: number;
  nonRefundableStorageFee: number;
  net: number;
  digest: string;
};
const rows: Row[] = [];
let RGP = 0n;

async function exec(label: string, tx: Transaction, signer = admin, expectFailure = false) {
  tx.setGasBudget(2_000_000_000);
  const res = await client.signAndExecuteTransaction({
    transaction: tx,
    signer,
    options: { showEffects: true, showObjectChanges: true, showEvents: true },
  });
  await client.waitForTransaction({ digest: res.digest });
  const g = res.effects!.gasUsed;
  const status = res.effects!.status.status === "success" ? "success" : `failure: ${res.effects!.status.error}`;
  const row: Row = {
    label,
    status,
    computationCost: Number(g.computationCost),
    storageCost: Number(g.storageCost),
    storageRebate: Number(g.storageRebate),
    nonRefundableStorageFee: Number(g.nonRefundableStorageFee),
    net: Number(g.computationCost) + Number(g.storageCost) - Number(g.storageRebate),
    digest: res.digest,
  };
  rows.push(row);
  console.log(`[gas] ${label}: ${JSON.stringify({ ...g, status })}`);
  if (!expectFailure && row.status !== "success") throw new Error(`${label} failed: ${row.status}`);
  return res;
}

const created = (res: any, typeFrag: string): string => {
  const c = res.objectChanges?.find((o: any) => o.type === "created" && o.objectType.includes(typeFrag));
  if (!c) throw new Error(`no created object matching ${typeFrag}`);
  return c.objectId;
};

async function nowMs(): Promise<bigint> {
  const o: any = await client.getObject({ id: "0x6", options: { showContent: true } });
  return BigInt(o.data.content.fields.timestamp_ms);
}
const poolEpoch = async () => (await nowMs()) / EPOCH_MS;
async function waitForEpoch(target: bigint) {
  for (;;) {
    const e = await poolEpoch();
    if (e >= target) return e;
    await new Promise((r) => setTimeout(r, 2000));
  }
}

// --------------------------------------------------------------------------------------------
async function main() {
  const poseidon = await buildPoseidon();
  const H = (xs: bigint[]): bigint => poseidon.F.toObject(poseidon(xs));
  const merklePath = (leaf: bigint, sib0: bigint, idx0: bigint) => {
    const pathElements = [sib0, ...Array(DEPTH - 1).fill(0n)];
    const pathIndices = [idx0, ...Array(DEPTH - 1).fill(0n)];
    let node = leaf;
    for (let i = 0; i < DEPTH; i++) node = pathIndices[i] === 0n ? H([node, pathElements[i]]) : H([pathElements[i], node]);
    return { pathElements, pathIndices, root: node };
  };
  const load = (dir: string, name: string) => ({
    wasm: join(CIRCUITS, dir, `${name}_js`, `${name}.wasm`),
    zkey: join(CIRCUITS, dir, `${name}_final.zkey`),
    vkPath: join(CIRCUITS, dir, `${name}_vk.json`),
    vk: JSON.parse(readFileSync(join(CIRCUITS, dir, `${name}_vk.json`), "utf-8")),
  });
  const art = { transfer: load("build", "transfer"), withdraw: load("build-withdraw", "withdraw"), compliance: load("build-compliance", "compliance") };
  const vkBytes = {
    transfer: vkToSuiBytes(art.transfer.vk),
    withdraw: vkToSuiBytes(art.withdraw.vk),
    compliance: vkToSuiBytes(art.compliance.vk),
  };
  console.log(`[info] VK bytes: transfer=${vkBytes.transfer.length} withdraw=${vkBytes.withdraw.length} compliance=${vkBytes.compliance.length}`);

  const prove = async (which: keyof typeof art, input: Record<string, any>) => {
    const s: any = {};
    for (const [k, v] of Object.entries(input)) s[k] = Array.isArray(v) ? v.map(String) : String(v);
    const out = execFileSync("node", [join(__dirname, "prove-cli.mjs"), art[which].wasm, art[which].zkey, art[which].vkPath], { input: JSON.stringify(s), maxBuffer: 1 << 24 });
    const { ok, proof, publicSignals } = JSON.parse(out.toString());
    if (!ok) throw new Error(`${which}: local verify failed`);
    return { proof: proofToSuiBytes(proof), inputs: publicInputsToSuiBytes(publicSignals), signals: publicSignals as string[] };
  };

  // ---- fund ----------------------------------------------------------------------------------
  for (const kp of [admin, mallory]) await requestSuiFromFaucetV2({ host: FAUCET, recipient: kp.toSuiAddress() });
  await new Promise((r) => setTimeout(r, 3000));
  RGP = BigInt(await client.getReferenceGasPrice());
  console.log(`[info] reference gas price: ${RGP} MIST/unit`);
  const ver: any = await client.getProtocolConfig();
  console.log(`[info] protocol version: ${ver.protocolVersion}`);

  // ---- publish -------------------------------------------------------------------------------
  const { modules, dependencies } = JSON.parse(readFileSync(BYTECODE!, "utf-8"));
  const pub = new Transaction();
  const [upgradeCap] = pub.publish({ modules, dependencies });
  pub.transferObjects([upgradeCap], admin.toSuiAddress());
  const pubRes = await exec("publish (package)", pub);
  const pkg = pubRes.objectChanges!.find((o: any) => o.type === "published") as any;
  const PKG = pkg.packageId as string;
  const treasury = created(pubRes, "TreasuryCap");

  // ---- create_pool ---------------------------------------------------------------------------
  let tx = new Transaction();
  tx.moveCall({ target: `${PKG}::pool::create_pool`, arguments: [tx.pure.vector("u8", Array.from(vkBytes.transfer)), tx.pure.u64(THRESHOLD), tx.pure.u64(EPOCH_MS)] });
  const poolRes = await exec("create_pool", tx);
  const POOL = created(poolRes, "::pool::Pool");
  const CAP = created(poolRes, "::pool::AdminCap");

  tx = new Transaction();
  tx.moveCall({ target: `${PKG}::token_faucet::faucet`, arguments: [tx.object(treasury)] });
  const fRes = await exec("token_faucet::faucet (test-only)", tx);
  const coin = created(fRes, "::token::TOKEN");

  // ---- secrets & commitments -----------------------------------------------------------------
  const userSecret = 987654321n;
  // C_t: shielded_transfer, C_c: compliant_transfer (both under the same Merkle root),
  // C_w1: honest zk_withdraw, C_w2: front-running probe
  const tIn = { cum: 0n, r: 0n };
  const cIn = { cum: 0n, r: 1n };
  const w1In = { cum: 500n, r: 12345n };
  const w2In = { cum: 500n, r: 54321n };
  // C_inf: inflation probe — deposits 100 TOKEN but commits to a balance of 300 TOKEN
  const infIn = { cum: 3n * DENOM, r: 999n };
  const comm = (x: { cum: bigint; r: bigint }) => H([D.COMMITMENT, x.cum, x.r, userSecret]);
  const C_t = comm(tIn), C_c = comm(cIn), C_w1 = comm(w1In), C_w2 = comm(w2In), C_inf = comm(infIn);
  const le32 = (n: bigint) => Array.from(publicInputsToSuiBytes([n.toString()]));

  const deposits: [string, bigint][] = [["C_t", C_t], ["C_c", C_c], ["C_w1", C_w1], ["C_w2", C_w2], ["C_inf (probe)", C_inf]];
  for (const [name, c] of deposits) {
    tx = new Transaction();
    const [part] = tx.splitCoins(tx.object(coin), [tx.pure.u64(DENOM)]);
    tx.moveCall({ target: `${PKG}::pool::deposit_and_register`, arguments: [tx.object(POOL), part, tx.pure.vector("u8", le32(c)), tx.object("0x6")] });
    await exec(`deposit_and_register (${name})`, tx);
  }

  const pathT = merklePath(C_t, C_c, 0n);
  const pathC = merklePath(C_c, C_t, 1n);
  if (pathT.root !== pathC.root) throw new Error("merkle roots disagree");

  tx = new Transaction();
  tx.moveCall({ target: `${PKG}::pool::update_commitment_root`, arguments: [tx.object(POOL), tx.object(CAP), tx.pure.vector("u8", le32(pathT.root)), tx.object("0x6")] });
  await exec("update_commitment_root (admin, timelocked)", tx);

  tx = new Transaction();
  tx.moveCall({ target: `${PKG}::pool::propose_withdraw_vk`, arguments: [tx.object(POOL), tx.object(CAP), tx.pure.vector("u8", Array.from(vkBytes.withdraw)), tx.object("0x6")] });
  await exec("propose_withdraw_vk (admin, timelocked)", tx);

  // credential tree (single leaf, zero siblings) — mirrors witnesses.mjs buildComplianceWitness
  const E0 = await poolEpoch();
  const cred = { kycLevel: 2n, expiryEpoch: E0 + 1_000_000n, issuerId: 42n };
  const credLeaf = H([D.CRED_LEAF, userSecret, cred.kycLevel, cred.expiryEpoch, cred.issuerId]);
  let credRoot = credLeaf;
  for (let i = 0; i < DEPTH; i++) credRoot = H([credRoot, 0n]);
  const auditorKey = Array.from({ length: 33 }, (_, i) => (i === 0 ? 2 : i));

  tx = new Transaction();
  tx.moveCall({
    target: `${PKG}::compliance::create_compliance_config`,
    arguments: [tx.object(CAP), tx.object(POOL), tx.pure.vector("u8", Array.from(vkBytes.compliance)), tx.pure.vector("u8", le32(credRoot)), tx.pure.u64(1), tx.pure.vector("u8", auditorKey)],
  });
  const ccRes = await exec("create_compliance_config", tx);
  const CONFIG = created(ccRes, "::compliance::ComplianceConfig");

  // admin ops
  tx = new Transaction();
  tx.moveCall({ target: `${PKG}::pool::propose_vk_update`, arguments: [tx.object(POOL), tx.object(CAP), tx.pure.vector("u8", Array.from(vkBytes.transfer)), tx.object("0x6")] });
  await exec("propose_vk_update (admin)", tx);
  tx = new Transaction();
  tx.moveCall({ target: `${PKG}::pool::cancel_vk_update`, arguments: [tx.object(POOL), tx.object(CAP)] });
  await exec("cancel_vk_update (admin)", tx);
  tx = new Transaction();
  tx.moveCall({ target: `${PKG}::pool::freeze_pool`, arguments: [tx.object(POOL), tx.object(CAP), tx.object("0x6")] });
  await exec("freeze_pool (admin)", tx);
  tx = new Transaction();
  tx.moveCall({ target: `${PKG}::pool::unfreeze_pool`, arguments: [tx.object(POOL), tx.object(CAP)] });
  await exec("unfreeze_pool (admin)", tx);

  // ---- groth16 micro-benchmarks (PTBs straight into 0x2::groth16, no Veil code) --------------
  for (const [name, vk] of Object.entries(vkBytes)) {
    tx = new Transaction();
    const curve = tx.moveCall({ target: "0x2::groth16::bn254" });
    tx.moveCall({ target: "0x2::groth16::prepare_verifying_key", arguments: [curve, tx.pure.vector("u8", Array.from(vk))] });
    await exec(`micro: groth16::prepare_verifying_key (${name} vk, ${vk.length} B)`, tx);
  }
  tx = new Transaction();
  tx.moveCall({ target: "0x2::groth16::bn254" });
  await exec("micro: empty PTB (groth16::bn254 only) — fixed overhead", tx);

  // ---- wait for E1 ---------------------------------------------------------------------------
  console.log(`[info] pool epoch E0=${E0}; waiting for E0+1 so timelocks + commitment maturity resolve...`);
  const E1 = await waitForEpoch(E0 + 1n);
  console.log(`[info] now in pool epoch ${E1}`);

  // transfer proof (epoch E1)
  const tAmt = 100n, tRandNew = 12345n, tSalt = 99n;
  const transferInput = (x: { cum: bigint; r: bigint }, path: any, randNew: bigint) => ({
    oldCommitment: comm(x),
    newCommitment: H([D.COMMITMENT, x.cum + tAmt, randNew, userSecret]),
    threshold: THRESHOLD, epochId: E1,
    nullifier: H([D.NULLIFIER, userSecret, E1, x.r]),
    txAmountHash: H([D.TX_AMOUNT, tAmt, tSalt]),
    merkleRoot: path.root,
    cumulativeOld: x.cum, cumulativeNew: x.cum + tAmt, txAmount: tAmt, randomnessOld: x.r, randomnessNew: randNew,
    userSecret, salt: tSalt, pathElements: path.pathElements, pathIndices: path.pathIndices,
  });
  const tp = await prove("transfer", transferInput(tIn, pathT, tRandNew));

  // full verify as a micro-benchmark (prepare + verify in one PTB, no Veil code)
  tx = new Transaction();
  {
    const curve = tx.moveCall({ target: "0x2::groth16::bn254" });
    const pvk = tx.moveCall({ target: "0x2::groth16::prepare_verifying_key", arguments: [curve, tx.pure.vector("u8", Array.from(vkBytes.transfer))] });
    const pts = tx.moveCall({ target: "0x2::groth16::proof_points_from_bytes", arguments: [tx.pure.vector("u8", Array.from(tp.proof))] });
    const ins = tx.moveCall({ target: "0x2::groth16::public_proof_inputs_from_bytes", arguments: [tx.pure.vector("u8", Array.from(tp.inputs))] });
    const curve2 = tx.moveCall({ target: "0x2::groth16::bn254" });
    tx.moveCall({ target: "0x2::groth16::verify_groth16_proof", arguments: [curve2, pvk, ins, pts] });
  }
  await exec("micro: prepare_verifying_key + verify_groth16_proof (transfer, 7 inputs)", tx);

  // Scaling micro-benchmarks. Every single-call PTB above lands on the 1,000-unit computation
  // floor, which hides the true cost. Repeating the op k times in one PTB lifts the total above
  // the floor; the slope between two k values is the per-op cost.
  //   base(k):    k x groth16::bn254()                          — per-command PTB overhead
  //   prep(k):    k x (bn254 + prepare_verifying_key)
  //   full(k):    k x (bn254 + prepare + proof/input parsing + verify)   — what Veil does today
  //   cached(k):  1 x prepare, then k x (bn254 + parsing + verify)       — PVK stored/reused
  const vkArg = (t: Transaction) => t.pure.vector("u8", Array.from(vkBytes.transfer));
  const scaling = async (k: number) => {
    let t = new Transaction();
    for (let i = 0; i < k; i++) t.moveCall({ target: "0x2::groth16::bn254" });
    await exec(`scale: base k=${k}`, t);

    t = new Transaction();
    { const vk = vkArg(t); for (let i = 0; i < k; i++) { const c = t.moveCall({ target: "0x2::groth16::bn254" }); t.moveCall({ target: "0x2::groth16::prepare_verifying_key", arguments: [c, vk] }); } }
    await exec(`scale: prep k=${k}`, t);

    t = new Transaction();
    {
      const vk = vkArg(t), pb = t.pure.vector("u8", Array.from(tp.proof)), ib = t.pure.vector("u8", Array.from(tp.inputs));
      for (let i = 0; i < k; i++) {
        const c = t.moveCall({ target: "0x2::groth16::bn254" });
        const pvk = t.moveCall({ target: "0x2::groth16::prepare_verifying_key", arguments: [c, vk] });
        const pts = t.moveCall({ target: "0x2::groth16::proof_points_from_bytes", arguments: [pb] });
        const ins = t.moveCall({ target: "0x2::groth16::public_proof_inputs_from_bytes", arguments: [ib] });
        const c2 = t.moveCall({ target: "0x2::groth16::bn254" });
        t.moveCall({ target: "0x2::groth16::verify_groth16_proof", arguments: [c2, pvk, ins, pts] });
      }
    }
    await exec(`scale: full k=${k}`, t);

    t = new Transaction();
    {
      const pb = t.pure.vector("u8", Array.from(tp.proof)), ib = t.pure.vector("u8", Array.from(tp.inputs));
      const c0 = t.moveCall({ target: "0x2::groth16::bn254" });
      const pvk = t.moveCall({ target: "0x2::groth16::prepare_verifying_key", arguments: [c0, vkArg(t)] });
      for (let i = 0; i < k; i++) {
        const pts = t.moveCall({ target: "0x2::groth16::proof_points_from_bytes", arguments: [pb] });
        const ins = t.moveCall({ target: "0x2::groth16::public_proof_inputs_from_bytes", arguments: [ib] });
        const c2 = t.moveCall({ target: "0x2::groth16::bn254" });
        t.moveCall({ target: "0x2::groth16::verify_groth16_proof", arguments: [c2, pvk, ins, pts] });
      }
    }
    await exec(`scale: cached k=${k}`, t);
  };
  for (const k of [25, 50, 100]) await scaling(k);

  const stCall = (t: Transaction) =>
    t.moveCall({ target: `${PKG}::pool::shielded_transfer`, arguments: [t.object(POOL), t.pure.vector("u8", Array.from(tp.proof)), t.pure.vector("u8", Array.from(tp.inputs)), t.object("0x6")] });
  tx = new Transaction(); stCall(tx);
  await exec("shielded_transfer", tx);
  tx = new Transaction(); stCall(tx);
  await exec("shielded_transfer replay (expected abort: commitment consumed)", tx, admin, true);

  // withdraw proofs
  const recipientField = (addr: string) => BigInt(addr) % P;
  const withdrawInput = (x: { cum: bigint; r: bigint }, recipient: bigint, randNew: bigint, wAmt = 100n) => ({
    commitment: comm(x), withdrawAmount: wAmt,
    nullifier: H([D.WD_NF, userSecret, x.r, x.cum]),
    recipientHash: H([D.RECIPIENT, recipient]),
    newCommitment: H([D.COMMITMENT, x.cum - wAmt, randNew, userSecret]),
    cumulativeOld: x.cum, randomnessOld: x.r, userSecret, recipient, randomnessNew: randNew,
  });
  const aliceAddr = admin.toSuiAddress();
  const wp1 = await prove("withdraw", withdrawInput(w1In, recipientField(aliceAddr), 77777n));
  tx = new Transaction();
  tx.moveCall({ target: `${PKG}::pool::zk_withdraw`, arguments: [tx.object(POOL), tx.pure.vector("u8", Array.from(wp1.proof)), tx.pure.vector("u8", Array.from(wp1.inputs)), tx.pure.address(aliceAddr), tx.object("0x6")] });
  await exec("zk_withdraw (first call — applies pending withdraw VK)", tx);

  // front-running probe: proof commits to Alice's recipientHash, Mallory submits with herself as recipient
  const wp2 = await prove("withdraw", withdrawInput(w2In, recipientField(aliceAddr), 88888n));
  const malAddr = mallory.toSuiAddress();
  tx = new Transaction();
  tx.moveCall({ target: `${PKG}::pool::zk_withdraw`, arguments: [tx.object(POOL), tx.pure.vector("u8", Array.from(wp2.proof)), tx.pure.vector("u8", Array.from(wp2.inputs)), tx.pure.address(malAddr), tx.object("0x6")] });
  const frRes = await exec("zk_withdraw FRONT-RUN PROBE (proof bound to Alice, recipient arg = Mallory)", tx, mallory, true);
  const frontRunSucceeded = frRes.effects!.status.status === "success";
  const malBal = await client.getBalance({ owner: malAddr, coinType: `${PKG}::token::TOKEN` });
  console.log(`[probe] front-run tx status=${frRes.effects!.status.status}; Mallory TOKEN balance after = ${malBal.totalBalance}`);

  // inflation probe: commitment C_inf was registered with a 100-TOKEN deposit but commits to a
  // 300-TOKEN balance. Withdraw 250 TOKEN — 150 more than was ever deposited against it.
  const infAmt = 250_000_000n;
  const wp3 = await prove("withdraw", withdrawInput(infIn, recipientField(malAddr), 99999n, infAmt));
  const balBefore = BigInt((await client.getBalance({ owner: malAddr, coinType: `${PKG}::token::TOKEN` })).totalBalance);
  tx = new Transaction();
  tx.moveCall({ target: `${PKG}::pool::zk_withdraw`, arguments: [tx.object(POOL), tx.pure.vector("u8", Array.from(wp3.proof)), tx.pure.vector("u8", Array.from(wp3.inputs)), tx.pure.address(malAddr), tx.object("0x6")] });
  const infRes = await exec("zk_withdraw INFLATION PROBE (deposited 100 TOKEN, withdraws 250 TOKEN)", tx, mallory, true);
  const inflationSucceeded = infRes.effects!.status.status === "success";
  const balAfter = BigInt((await client.getBalance({ owner: malAddr, coinType: `${PKG}::token::TOKEN` })).totalBalance);
  console.log(`[probe] inflation tx status=${infRes.effects!.status.status}; Mallory TOKEN ${balBefore} -> ${balAfter} (deposit was ${DENOM})`);

  // compliant_transfer (transfer proof on C_c + compliance proof bound to its nullifier)
  const cTransfer = transferInput(cIn, pathC, 22222n);
  const ctp = await prove("transfer", cTransfer);
  const contextId = H([D.CONTEXT, cTransfer.nullifier, userSecret]);
  const cpIn = {
    merkleRoot: credRoot, currentEpoch: E1, contextId, requiredKycLevel: 1n,
    nullifier: H([D.COMPL_NF, userSecret, contextId]), validCredential: 1n,
    userSecret, kycLevel: cred.kycLevel, expiryEpoch: cred.expiryEpoch, issuerId: cred.issuerId,
    pathElements: Array(DEPTH).fill(0n), pathIndices: Array(DEPTH).fill(0n), transferNullifier: cTransfer.nullifier,
  };
  const cp = await prove("compliance", cpIn);
  const encryptedAmount = Array.from({ length: 93 }, (_, i) => i & 0xff); // minimum length accepted (MIN_ENCRYPTED_AMOUNT_LEN)
  tx = new Transaction();
  tx.moveCall({
    target: `${PKG}::compliance::compliant_transfer`,
    arguments: [tx.object(POOL), tx.object(CONFIG), tx.pure.vector("u8", Array.from(ctp.proof)), tx.pure.vector("u8", Array.from(ctp.inputs)), tx.pure.vector("u8", Array.from(cp.proof)), tx.pure.vector("u8", Array.from(cp.inputs)), tx.pure.vector("u8", encryptedAmount), tx.object("0x6")],
  });
  await exec("compliant_transfer (transfer + compliance proof)", tx);

  // ---- report --------------------------------------------------------------------------------
  console.log(`\n## Gas (MIST at RGP=${RGP}; computation units = computationCost / RGP)\n`);
  console.log("| Entry point | Status | Computation (MIST) | Units | Storage cost | Storage rebate | Net (MIST) |");
  console.log("|---|---|---|---|---|---|---|");
  for (const r of rows) {
    console.log(`| ${r.label} | ${r.status.startsWith("success") ? "ok" : r.status.slice(0, 60)} | ${r.computationCost} | ${Number(BigInt(r.computationCost) / RGP)} | ${r.storageCost} | ${r.storageRebate} | ${r.net} |`);
  }
  console.log(`\n[probe] FRONT_RUN_SUCCEEDED=${frontRunSucceeded}`);
  console.log(`[probe] INFLATION_SUCCEEDED=${inflationSucceeded}`);
  if (JSON_OUT) writeFileSync(JSON_OUT, JSON.stringify({ rgp: Number(RGP), protocolVersion: ver.protocolVersion, rows, frontRunSucceeded, inflationSucceeded }, null, 2));
}

main().then(() => process.exit(0)).catch((e) => {
  console.error("[FATAL]", e);
  process.exit(1);
});
